--
-- Disparadores `paal_compras`
--
DELIMITER $$
CREATE TRIGGER `cancelar_compra` AFTER UPDATE ON `paal_compras` FOR EACH ROW BEGIN

    IF (NEW.status != OLD.status AND NEW.status = 'cancelado') THEN

        UPDATE paal_compra_productos SET

            cancelado = 'si'

        WHERE

            id_compra = OLD.id_compra;

    END IF;

END
$$
DELIMITER ;

