--
-- Estructura de tabla para la tabla `paal_compra_productos`
--

CREATE TABLE `paal_compra_productos` (
  `id_compra_producto` int NOT NULL,
  `id_compra` int NOT NULL,
  `id_producto` int NOT NULL,
  `nombre_producto` varchar(250) COLLATE utf8mb4_bin DEFAULT NULL,
  `cantidad` decimal(22,2) NOT NULL,
  `precio_original` decimal(22,2) NOT NULL,
  `precio_costo` decimal(22,2) NOT NULL,
  `cancelado` enum('si','no') COLLATE utf8mb4_bin DEFAULT 'no',
  `aplica_iva` enum('si','no') COLLATE utf8mb4_bin NOT NULL DEFAULT 'si',
  `subtotal` decimal(22,2) NOT NULL DEFAULT '0.00',
  `iva` decimal(22,2) NOT NULL DEFAULT '0.00',
  `descuento` decimal(22,2) NOT NULL DEFAULT '0.00',
  `total` decimal(22,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

--
-- Disparadores `paal_compra_productos`
--
DELIMITER $$
CREATE TRIGGER `cancelar_compra_producto` AFTER UPDATE ON `paal_compra_productos` FOR EACH ROW BEGIN

    DECLARE tipo_movimiento_compra VARCHAR(100);

    DECLARE id_sucursal_compra VARCHAR(100);

    

    SET tipo_movimiento_compra = (SELECT tipo FROM paal_compras WHERE id_compra = NEW.id_compra LIMIT 1);

    SET id_sucursal_compra = (SELECT id_sucursal FROM paal_compras WHERE id_compra = NEW.id_compra LIMIT 1);



    IF (NEW.cancelado != OLD.cancelado AND NEW.cancelado = 'si') THEN

        IF (tipo_movimiento_compra = 'incremento') THEN

            UPDATE paal_inventario SET

                stock = stock - OLD.cantidad

            WHERE

                id_producto = OLD.id_producto AND

                id_sucursal = id_sucursal_compra;

        END IF;



        IF (tipo_movimiento_compra = 'decremento') THEN

            UPDATE paal_inventario SET

                stock = stock + OLD.cantidad

            WHERE

                id_producto = OLD.id_producto AND

                id_sucursal = id_sucursal_compra;

        END IF;

    END IF;

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `compra` AFTER INSERT ON `paal_compra_productos` FOR EACH ROW BEGIN

    DECLARE tipo_movimiento_compra VARCHAR(100);

    DECLARE id_sucursal_compra VARCHAR(100);

    

    SET tipo_movimiento_compra = (SELECT tipo FROM paal_compras WHERE id_compra = NEW.id_compra LIMIT 1);

    SET id_sucursal_compra = (SELECT id_sucursal FROM paal_compras WHERE id_compra = NEW.id_compra LIMIT 1);



    IF (tipo_movimiento_compra = 'incremento') THEN

        UPDATE paal_inventario SET

            stock = stock + NEW.cantidad

        WHERE

            id_producto = NEW.id_producto AND

            id_sucursal = id_sucursal_compra;

    END IF;



    IF (tipo_movimiento_compra = 'decremento') THEN

        UPDATE paal_inventario SET

            stock = stock - NEW.cantidad

        WHERE

            id_producto = NEW.id_producto AND

            id_sucursal = id_sucursal_compra;

    END IF;



END
$$
DELIMITER ;

