--

CREATE TABLE `paal_inventario_ajustes` (
  `id_inventario_ajuste` int NOT NULL,
  `id_usuario` int NOT NULL,
  `id_sucursal` int NOT NULL,
  `folio` varchar(20) COLLATE utf8mb4_bin NOT NULL,
  `observaciones` varchar(250) COLLATE utf8mb4_bin DEFAULT NULL,
  `status` enum('activo','cancelado') COLLATE utf8mb4_bin NOT NULL DEFAULT 'activo',
  `tipo` enum('incremento','decremento') COLLATE utf8mb4_bin NOT NULL,
  `motivo_ajuste` varchar(250) COLLATE utf8mb4_bin DEFAULT NULL,
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tipo_ajuste` enum('merma','perdida','muestra','ajuste') COLLATE utf8mb4_bin NOT NULL DEFAULT 'ajuste'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

--
-- Disparadores `paal_inventario_ajustes`
--
DELIMITER $$
CREATE TRIGGER `inventario_cancelar_ajuste` AFTER UPDATE ON `paal_inventario_ajustes` FOR EACH ROW BEGIN
    IF (NEW.status != OLD.status AND NEW.status = 'cancelado') THEN
        UPDATE paal_inventario_ajuste_productos SET
            cancelado = 'si'
        WHERE
            id_inventario_ajuste = OLD.id_inventario_ajuste;
    END IF;
END
$$
DELIMITER ;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `paal_inventario_ajuste_productos`
--

CREATE TABLE `paal_inventario_ajuste_productos` (
  `id_inventario_ajuste_producto` int NOT NULL,
  `id_inventario_ajuste` int NOT NULL,
  `id_producto` int NOT NULL,
  `cantidad` decimal(22,2) NOT NULL,
  `cancelado` enum('no','si') COLLATE utf8mb4_bin NOT NULL DEFAULT 'no'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

--
-- Disparadores `paal_inventario_ajuste_productos`
--
DELIMITER $$
CREATE TRIGGER `inventario_ajuste` AFTER INSERT ON `paal_inventario_ajuste_productos` FOR EACH ROW BEGIN
    DECLARE ia_tipo_movimiento VARCHAR(100);
    DECLARE ia_id_sucursal VARCHAR(100);
    
    SET ia_tipo_movimiento = (SELECT tipo FROM paal_inventario_ajustes WHERE id_inventario_ajuste = NEW.id_inventario_ajuste LIMIT 1);
    SET ia_id_sucursal = (SELECT id_sucursal FROM paal_inventario_ajustes WHERE id_inventario_ajuste = NEW.id_inventario_ajuste LIMIT 1);

    IF (ia_tipo_movimiento = 'incremento') THEN
        UPDATE paal_inventario SET
            stock = stock + NEW.cantidad
        WHERE
            id_producto = NEW.id_producto AND
            id_sucursal = ia_id_sucursal;
    END IF;

    IF (ia_tipo_movimiento = 'decremento') THEN
        UPDATE paal_inventario SET
            stock = stock - NEW.cantidad
        WHERE
            id_producto = NEW.id_producto AND
            id_sucursal = ia_id_sucursal;
    END IF;

END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `inventario_cancelar_ajuste_producto` AFTER UPDATE ON `paal_inventario_ajuste_productos` FOR EACH ROW BEGIN
    DECLARE ia_tipo_movimiento VARCHAR(100);
    DECLARE ia_id_sucursal VARCHAR(100);
    
    SET ia_tipo_movimiento = (SELECT tipo FROM paal_inventario_ajustes WHERE id_inventario_ajuste = NEW.id_inventario_ajuste LIMIT 1);
    SET ia_id_sucursal = (SELECT id_sucursal FROM paal_inventario_ajustes WHERE id_inventario_ajuste = NEW.id_inventario_ajuste LIMIT 1);

    IF (NEW.cancelado != OLD.cancelado AND NEW.cancelado = 'si') THEN
        UPDATE paal_inventario_ajuste_producto_numeros_serie SET cancelado = 'si' WHERE id_inventario_ajuste_producto = NEW.id_inventario_ajuste_producto;

        IF (ia_tipo_movimiento = 'incremento') THEN
            UPDATE paal_inventario SET
                stock = stock - OLD.cantidad
            WHERE
                id_producto = OLD.id_producto AND
                id_sucursal = ia_id_sucursal;
        END IF;

        IF (ia_tipo_movimiento = 'decremento') THEN
            UPDATE paal_inventario SET
                stock = stock + OLD.cantidad
            WHERE
                id_producto = OLD.id_producto AND
                id_sucursal = ia_id_sucursal;
        END IF;
    END IF;
END
$$
DELIMITER ;

