  `transferencia_referencia` varchar(250) COLLATE utf8mb4_bin DEFAULT NULL,
  `tarjeta_credito` decimal(22,2) NOT NULL DEFAULT '0.00',
  `tarjeta_credito_referencia` varchar(250) COLLATE utf8mb4_bin DEFAULT NULL,
  `tarjeta_credito_numero` varchar(100) COLLATE utf8mb4_bin DEFAULT NULL,
