  `status` enum('activo','cancelado') COLLATE utf8mb4_bin NOT NULL DEFAULT 'activo',
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `tipo_productos` enum('equipo','llantas','rines','refacciones','servicios','otros','mixto') COLLATE utf8mb4_bin NOT NULL
