--
-- Disparadores `paal_ventas`
--
DELIMITER $$
CREATE TRIGGER `cancelar_venta` AFTER UPDATE ON `paal_ventas` FOR EACH ROW BEGIN
    IF (NEW.status != OLD.status AND NEW.status = 'cancelado') THEN
        UPDATE paal_venta_productos SET
            cancelado = 'si'
        WHERE
            id_venta = OLD.id_venta;
    END IF;
END
$$
DELIMITER ;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `paal_venta_productos`
--

CREATE TABLE `paal_venta_productos` (
  `id_venta_producto` int NOT NULL,
  `id_venta` int NOT NULL,
  `id_producto` int NOT NULL,
  `nombre_producto` varchar(250) COLLATE utf8mb4_bin NOT NULL,
  `precio_venta` decimal(22,2) NOT NULL DEFAULT '0.00',
  `cantidad_mayoreo` decimal(22,2) NOT NULL DEFAULT '0.00',
  `precio_mayoreo` decimal(22,2) NOT NULL DEFAULT '0.00',
  `aplica_iva` enum('si','no') COLLATE utf8mb4_bin NOT NULL DEFAULT 'no',
  `precio_venta_base` decimal(22,2) NOT NULL DEFAULT '0.00',
  `cantidad` decimal(22,2) NOT NULL,
  `precio` decimal(22,2) NOT NULL DEFAULT '0.00',
  `iva` decimal(22,2) NOT NULL DEFAULT '0.00',
  `descuento` decimal(22,2) NOT NULL DEFAULT '0.00',
  `precio_neto` decimal(22,2) NOT NULL DEFAULT '0.00',
  `subtotal` decimal(22,2) NOT NULL DEFAULT '0.00',
  `total` decimal(22,2) NOT NULL DEFAULT '0.00',
  `cancelado` enum('si','no') COLLATE utf8mb4_bin NOT NULL DEFAULT 'no'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

--
-- Disparadores `paal_venta_productos`
--
DELIMITER $$
CREATE TRIGGER `cancelar_venta_producto` AFTER UPDATE ON `paal_venta_productos` FOR EACH ROW BEGIN
    DECLARE tipo_movimiento_venta VARCHAR(100);
    DECLARE id_sucursal_venta VARCHAR(100);
    
    SET tipo_movimiento_venta = (SELECT tipo FROM paal_ventas WHERE id_venta = NEW.id_venta LIMIT 1);
    SET id_sucursal_venta = (SELECT id_sucursal FROM paal_ventas WHERE id_venta = NEW.id_venta LIMIT 1);

    IF (NEW.cancelado != OLD.cancelado AND NEW.cancelado = 'si') THEN
        IF (tipo_movimiento_venta = 'incremento') THEN
            UPDATE paal_inventario SET
                stock = stock + OLD.cantidad
            WHERE
                id_producto = OLD.id_producto AND
                id_sucursal = id_sucursal_venta;
        END IF;

        IF (tipo_movimiento_venta = 'decremento') THEN
            UPDATE paal_inventario SET
                stock = stock - OLD.cantidad
            WHERE
                id_producto = OLD.id_producto AND
                id_sucursal = id_sucursal_venta;
        END IF;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `venta` AFTER INSERT ON `paal_venta_productos` FOR EACH ROW BEGIN
    DECLARE tipo_movimiento_venta VARCHAR(100);
    DECLARE id_sucursal_venta VARCHAR(100);
    
    SET tipo_movimiento_venta = (SELECT tipo FROM paal_ventas WHERE id_venta = NEW.id_venta LIMIT 1);
    SET id_sucursal_venta = (SELECT id_sucursal FROM paal_ventas WHERE id_venta = NEW.id_venta LIMIT 1);

    IF (tipo_movimiento_venta = 'incremento') THEN
        UPDATE paal_inventario SET
            stock = stock - NEW.cantidad
        WHERE
            id_producto = NEW.id_producto AND
            id_sucursal = id_sucursal_venta;
    END IF;

    IF (tipo_movimiento_venta = 'decremento') THEN
        UPDATE paal_inventario SET
            stock = stock + NEW.cantidad
        WHERE
            id_producto = NEW.id_producto AND
            id_sucursal = id_sucursal_venta;
    END IF;

END
$$
DELIMITER ;

